def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def col_row(name: str) -> tuple[int, int]:
        return ord(name[0]) - 65, int(name[1:])

    def range_names(a: str, b: str):
        c1, r1 = col_row(a)
        c2, r2 = col_row(b)
        if c1 > c2:
            c1, c2 = c2, c1
        if r1 > r2:
            r1, r2 = r2, r1
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                yield chr(65 + c) + str(r)

    def trunc_div(a: int, b: int) -> int | str:
        if b == 0:
            return "#DIV/0!"
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        def skip(self) -> None:
            while self.i < self.n and self.s[self.i] == " ":
                self.i += 1

        def peek(self) -> str:
            self.skip()
            return self.s[self.i] if self.i < self.n else ""

        def read_ident(self) -> str:
            self.skip()
            start = self.i
            self.i += 1
            if self.i < self.n and self.s[self.i].isalpha():
                while self.i < self.n and self.s[self.i].isalpha():
                    self.i += 1
            else:
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
            return self.s[start:self.i]

        def read_int(self) -> int:
            self.skip()
            start = self.i
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
            return int(self.s[start:self.i])

        def parse_cmp(self) -> str:
            self.skip()
            two = self.s[self.i : self.i + 2]
            if two in ("<>", "<=", ">="):
                self.i += 2
                return two
            op = self.s[self.i]
            self.i += 1
            return op

        def parse_expr(self):
            node = self.parse_term()
            while self.peek() in "+-":
                op = self.s[self.i]
                self.i += 1
                node = ("bin", op, node, self.parse_term())
            return node

        def parse_term(self):
            node = self.parse_unary()
            while self.peek() in "*/":
                op = self.s[self.i]
                self.i += 1
                node = ("bin", op, node, self.parse_unary())
            return node

        def parse_unary(self):
            if self.peek() == "-":
                self.i += 1
                return ("neg", self.parse_unary())
            return self.parse_atom()

        def parse_atom(self):
            ch = self.peek()
            if ch.isdigit():
                return ("num", self.read_int())
            if ch == "(":
                self.i += 1
                node = self.parse_expr()
                self.skip()
                self.i += 1
                return node
            ident = self.read_ident()
            if self.peek() == "(":
                return self.parse_call(ident)
            return ("cell", ident)

        def parse_arg(self):
            self.skip()
            mark = self.i
            if mark < self.n and self.s[mark].isalpha():
                ident = self.read_ident()
                if (
                    self.peek() == ":"
                    and len(ident) >= 2
                    and ident[0].isalpha()
                    and ident[1:].isdigit()
                ):
                    self.i += 1
                    return ("range", ident, self.read_ident())
                self.i = mark
            return self.parse_expr()

        def parse_call(self, name: str):
            self.skip()
            self.i += 1
            if name == "IF":
                left = self.parse_expr()
                op = self.parse_cmp()
                right = self.parse_expr()
                self.skip()
                self.i += 1
                then_b = self.parse_expr()
                self.skip()
                self.i += 1
                else_b = self.parse_expr()
                self.skip()
                self.i += 1
                return ("if", left, op, right, then_b, else_b)
            args = [self.parse_arg()]
            while self.peek() == ",":
                self.i += 1
                args.append(self.parse_arg())
            self.skip()
            self.i += 1
            return (name, args)

    def compare(op: str, a: int, b: int) -> bool:
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            v = ev(node[1])
            return v if isinstance(v, str) else -v
        if kind == "bin":
            _, op, left, right = node
            lv = ev(left)
            if isinstance(lv, str):
                return lv
            rv = ev(right)
            if isinstance(rv, str):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            return trunc_div(lv, rv)
        if kind == "if":
            _, left, op, right, then_b, else_b = node
            lv = ev(left)
            if isinstance(lv, str):
                return lv
            rv = ev(right)
            if isinstance(rv, str):
                return rv
            return ev(then_b if compare(op, lv, rv) else else_b)
        vals: list[int] = []
        for arg in node[1]:
            if arg[0] == "range":
                for name in range_names(arg[1], arg[2]):
                    if name not in cells:
                        continue
                    v = eval_cell(name)
                    if isinstance(v, str):
                        return v
                    vals.append(v)
            else:
                v = ev(arg)
                if isinstance(v, str):
                    return v
                vals.append(v)
        if kind == "SUM" or not vals:
            return sum(vals)
        return min(vals) if kind == "MIN" else max(vals)

    def eval_cell(name: str) -> int | str:
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        raw = cells[name].strip()
        if raw.startswith("="):
            val = ev(Parser(raw[1:]).parse_expr())
        else:
            val = int(raw)
        visiting.remove(name)
        memo[name] = val
        return val

    return {name: eval_cell(name) for name in cells}
